function jsonViewAllowed(url){return typeof url==='string'&&(/^\/api\/contract$/.test(url)||/^\/api\/reports\/[a-zA-Z0-9-]+$/.test(url)||/^\/api\/runs\/[a-zA-Z0-9-]+\/export\/json$/.test(url)||/^\/api\/availability\/[a-zA-Z0-9-]+\/report\?format=json$/.test(url));}
function jsonFieldLabel(key){return String(key).replace(/([a-z])([A-Z])/g,'$1 $2').replace(/[_-]+/g,' ').replace(/^./,c=>c.toUpperCase());}
function jsonSections(value,depth=0){
 if(value===null||typeof value!=='object')return '<span class="json-value">'+e(value===null?'Not provided':String(value))+'</span>';
 if(depth>=3)return '<pre class="code light">'+e(JSON.stringify(value,null,2))+'</pre>';
 const entries=Object.entries(value),limited=entries.slice(0,100);if(!entries.length)return '<p class="subtle">'+(Array.isArray(value)?'No entries.':'No fields.')+'</p>';
 return limited.map(([key,item])=>{const name=Array.isArray(value)?'Item '+(Number(key)+1):jsonFieldLabel(key);return item!==null&&typeof item==='object'?'<details class="json-section"><summary>'+e(name)+' <span class="subtle">'+Object.keys(item).length+' '+(Array.isArray(item)?'entries':'fields')+'</span></summary>'+jsonSections(item,depth+1)+'</details>':'<div class="json-field"><dt>'+e(name)+'</dt><dd>'+jsonSections(item,depth+1)+'</dd></div>';}).join('')+(entries.length>100?'<p class="footnote">First 100 entries shown here. The complete document below includes every entry.</p>':'');
}
function jsonDocumentViewer(doc,title,url){if(doc?.openapi&&doc?.paths)return schemaViewer(doc,null,url);return '<section class="json-document"><p class="smalltext">Structured view of the original data. Expand a section to inspect its contents.</p><div class="json-readable">'+jsonSections(doc)+'</div><details class="json-section space"><summary>Complete document · formatted JSON</summary><pre class="code light">'+e(JSON.stringify(doc,null,2))+'</pre></details><div class="buttons space"><a class="btn small" data-json-original href="'+e(url)+'" target="_blank" rel="noopener">Open original JSON</a><a class="btn small" data-json-original href="'+e(url)+'" download="geobridge-data.json">Download JSON</a></div></section>';}
document.addEventListener('click',async ev=>{const link=ev.target.closest?.('a[data-json-view]');if(!link)return;ev.preventDefault();const url=link.getAttribute('href'),title=link.dataset.jsonView||'Technical data';if(!jsonViewAllowed(url)){showError('Unsupported document link.');return;}modal(e(title),'<div class="json-loading" role="status">Loading document…</div>');const loading=document.querySelector('.json-loading');try{const doc=await api(url);if(!dialog.open||!loading?.isConnected)return;document.querySelector('.dialog-content').innerHTML='<div id="dialog-message" class="dialog-message" role="alert" tabindex="-1" hidden></div>'+jsonDocumentViewer(doc,title,url);}catch(error){if(dialog.open&&loading?.isConnected)showError(error.message);}});
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog'),toastEl=document.querySelector('#toast');
const state={user:null,csrf:'',workspace:null,page:null,run:null,filter:'all',busy:false,menuOpen:false};
